beforeExample:
package test;

import org.eclipse.jface.text.source.JFaceTextMessages;

public class Test {
    public void method(int lineNumber, Object annotationTypeLabel) {
        // Example 1: String[]
        String message1 = JFaceTextMessages.getFormattedString("key1", new String[] { Integer.toString(lineNumber + 1) });

        // Example 2: Object[] with multiple args
        Integer arg2 = Integer.valueOf(10);
        String message2 = JFaceTextMessages.getFormattedString("key2", new Object[] { annotationTypeLabel, arg2 });

        // Example 3: Object[] with single arg
        String message3 = JFaceTextMessages.getFormattedString("key3", new Object[] { "single" });
    }
}

