package test;

import org.eclipse.jface.text.source.JFaceTextMessages;

public class Test {
    public void method(int lineNumber, Object annotationTypeLabel) {
        // Example 1: String[]
        String message1 = JFaceTextMessages.getFormattedString("key1", Integer.toString(lineNumber + 1));

        // Example 2: Object[] with multiple args
        Integer arg2 = Integer.valueOf(10);
        String message2 = JFaceTextMessages.getFormattedString("key2", annotationTypeLabel, arg2);

        // Example 3: Object[] with single arg
        String message3 = JFaceTextMessages.getFormattedString("key3", "single");
    }
}

negativeExample:
package test;

import org.eclipse.jface.text.source.JFaceTextMessages;

public class Test {
    public void method() {
        // Should not match if already using varargs style
        String message1 = JFaceTextMessages.getFormattedString("key1", "arg1", "arg2");

        // Should not match if the method is not JFaceTextMessages.getFormattedString
        String[] args = { "a", "b" };
        java.lang.String.format("format", args);

        // Should not match if the array is not a direct argument of the method call
        String[] anArray = new String[]{"test"};
        System.out.println(anArray.length);
    }
}
